using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class SharedShelterChecks {
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void Verify()=>VerifyWithCapture(null);
 public static void VerifyWithCapture(Action<VillagerExploration,VillagerExploration,ConstructionSite> capture){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var site=god.GetComponent<CreatureConstructionLearning>().sites[0];var people=slice.GetComponentsInChildren<VillagerExploration>();var host=people[0];var guest=people[1];var nav=host.GetComponent<IslandNavigator>();
  var field=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=field.GetValue(slice);var geometry=site.Capture();var recipe=site.Recipe;bool paused=site.Paused;var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();
  god.Interrupt("Shared shelter QA");foreach(var person in people){person.ResetTask();person.GetComponent<VillagerSocial>().ResetTask();person.GetComponent<VillagerResourceGathering>().Cancel();person.GetComponent<VillagerBlockPlay>().ResetTask();}
  var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100};field.SetValue(slice,test);test.Hybrid.time=200;test.Weather.rain=1;slice.GetComponentInChildren<VillageFamilies>().ResetWorld();
  ConstructionBlock Put(ConstructionShape shape,Vector3 at){var block=site.blocks.First(b=>b.Shape==shape&&!b.Attached);Require(site.Drop(block,site.World(at),site.transform.rotation),"Shelter fixture failed: "+shape+" "+at);return block;}
  void Stage(){foreach(var person in people){person.ResetTask();person.GetComponent<CarryItem>().held=false;var route=person.GetComponent<IslandNavigator>();int index=Array.IndexOf(people,person);var desired=site.World(new Vector3(index==0?0:12,0,index<2?-25:-20+index*3));Require(route.world.Sample(desired,route.profile,8,out var at),"No shelter approach stage");person.transform.position=route.world.ProjectFoot(at,route.profile);route.ResetRoute();person.GetComponent<VillagerSocial>().Memory.nextGatheringAt=0;}host.ConfigurePeers(new[]{guest});test.Social(0).restNeed=.95f;}
  void Step(){test.Hybrid.time+=.05f;host.Tick(.05f,false);guest.Tick(.05f,false);}
  void HostArrives(){Require(host.TryShelter(site),"Host refused shelter");for(int i=0;i<1600&&host.Current!=VillagerExploration.Phase.UseStructure;i++){test.Hybrid.time+=.05f;host.Tick(.05f,false);}Require(host.Current==VillagerExploration.Phase.UseStructure,"Native host arrival failed");}
  try{
   site.Paused=false;site.ResetConstruction();site.Recipe=BuildRecipe.Tower;Put(ConstructionShape.Column,new Vector3(-2,2.4f,-12));Put(ConstructionShape.Column,new Vector3(2,2.4f,-12));var hostRoof=Put(ConstructionShape.Slab,new Vector3(0,5.4f,-12));Stage();HostArrives();Require(!host.Gathering&&!guest.TryJoinGathering(host),"One covered spot admitted overlapping guest");host.ResetTask();
   Put(ConstructionShape.Column,new Vector3(-2,2.4f,-18));Put(ConstructionShape.Column,new Vector3(2,2.4f,-18));var guestRoof=Put(ConstructionShape.Slab,new Vector3(0,5.4f,-18));Require(!site.RecipeComplete,"Fixture accidentally depended on a recipe");Stage();HostArrives();Require(host.Gathering&&guest.Gathering&&site.Visitor==host,"Second canopy did not enable native invitation");Require(!people[2].TryJoinGathering(host),"Third villager stole gathering");host.Tick(10,true);guest.Tick(10,true);Require(test.Social(0).sharedRests==0&&test.Social(1).sharedRests==0,"Pause completed shelter gathering");
   for(int i=0;i<1000&&test.Social(1).sharedRests==0;i++)Step();
   Require(test.Social(0).sharedRests==1&&test.Social(1).sharedRests==1,"Native covered gathering failed: host="+host.Current+", guest="+guest.Current+", blocked="+guest.GetComponent<IslandNavigator>().Blocked);
   capture?.Invoke(host,guest,site);Require(test.Social(0).Place(0)?.uncomfortable==0&&test.Social(1).Place(0)?.uncomfortable==0,"Second roof did not supply individual comfort");Require(test.Social(1).Peer(host.GetComponent<HybridTarget>().id)?.good==1&&test.Social(1).restNeed<.5f,"Covered company did not improve friendship/rest");
   for(int i=0;i<600&&site.Visitor!=null;i++)Step();Require(test.Social(0).shelterRests==1&&test.Social(0).Place(0).visits==1&&site.Visitor==null,"Host rest or place deduplication failed");var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid()&&saved.Social(1).sharedRests==1,"Shared shelter memory did not save");
   Stage();HostArrives();Require(guest.Gathering,"Removal invitation failed");site.ReturnLoose(guestRoof);guest.Tick(.3f,false);Require(!guest.Gathering&&!host.Gathering&&site.Visitor==host&&test.Social(1).sharedRests==1,"Lost guest roof retained gathering or canceled valid solo host");for(int i=0;i<600&&site.Visitor!=null;i++)Step();Require(test.Social(0).shelterRests==2&&site.Visitor==null,"Host could not finish valid solo rest after guest cancellation");host.ResetTask();
   Require(site.Drop(guestRoof,site.World(new Vector3(0,5.4f,-18)),site.transform.rotation),"Guest roof restoration failed");Stage();HostArrives();int restsBefore=test.Social(0).shelterRests;for(int i=0;i<600&&site.Visitor!=null;i++){test.Hybrid.time+=.05f;host.Tick(.05f,false);}Require(test.Social(0).shelterRests==restsBefore+1&&site.Visitor==null&&!guest.Gathering&&test.Social(1).sharedRests==1,"Waiting for an unresponsive guest retained host/lease or invented shared rest");
   Stage();HostArrives();guest.GetComponent<CarryItem>().held=true;guest.Tick(.05f,false);guest.GetComponent<CarryItem>().held=false;Require(!host.Gathering&&!guest.Gathering&&test.Social(1).sharedRests==1,"Pickup retained social reservation/reward");host.ResetTask();
   Stage();HostArrives();site.ReturnLoose(hostRoof);host.Tick(.3f,false);Require(site.Visitor==null&&!host.Gathering&&!guest.Gathering&&test.Social(1).sharedRests==1,"Lost host roof retained participants or credit");
   Debug.Log("BWVR_SHARED_SHELTER_PASS: geometry capacity, native host invitation and guest approach, covered rainy friendship/rest, exclusive guest, pause, once-only saved place memory, lost guest/host cover and pickup cleanup");
  }finally{foreach(var person in people){person.GetComponent<CarryItem>().held=false;person.ResetTask();person.ConfigurePeers(people);}site.Recipe=recipe;site.Restore(geometry);site.Paused=paused;for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}field.SetValue(slice,original);}
 }
}
}
